  q(655,"recall","Lateral corticospinal tract is qualified as:","(Pyramidal) tract","Uncrossed only","The only extrapyramidal path","A dorsal-column fasciculus",exp="Lateral corticospinal (Pyramidal) tract"),
  q(655,"recall","Lateral corticospinal and rubrospinal tracts are bracketed to:","Distal limb movements","Axial and proximal limb movements","Pain, temperature","Pressure, touch",exp="Bracket: Distal limb movements"),
  q(655,"recall","Vestibulospinal, ventral reticulospinal and tectospinal tracts are bracketed to:","Axial and proximal limb movements","Distal limb movements","Pain, temperature","Fine touch",exp="Bracket: Axial and proximal limb movements"),
  q(655,"recall","Myelopathies are defined as:","Sensory/Autonomic/motor symptoms d/t spinal cord disease","Peripheral nerve demyelination","NMJ antibody disease","Anterior horn cell SOD defect only",exp="Myelopathies : Sensory/Autonomic/motor symptoms d/t spinal cord disease"),
  q(655,"recall","Non-compressive myelopathy in the flowchart is:","Transverse myelitis","Disc compression","Ependymoma","Syringomyelia",exp="Non-compressive : Transverse myelitis"),
